<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\UploadContent;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetUploadContentUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateAssetVisibilityService $visibility,
    private readonly TemplateAssetWriteGateway $writer
  ) {
  }

  public function allowUpload(): Allow
  {
    $this->logDebug("Check allow of temp upload Content usecase for Template asset");
    $span = $this->startSpan("Check allow of temp upload Content usecase for Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetUploadContentAllowDecision(Allow::allowed('upload', 'Allowed to upload by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function readTemporal(string $query): BinaryContent
  {
    $this->logDebug("Run retrieve temp upload Content usecase for Template asset");
    $span = $this->startSpan("Run retrieve temp upload Content usecase for Template asset");
    try {
      $allow = $this->allowUpload();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to read tempora upload for Template asset');
      }
      return $this->writer->readTemporalContent($query);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function temporalStore(BinaryContent $binary): string
  {
    $this->logDebug("Run temp upload Content usecase for Template asset");
    $span = $this->startSpan("Run temp upload Content usecase for Template asset");
    try {
      $allow = $this->allowUpload();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to upload store on Template asset');
      }
      $this->dispatcher->dispatch(new TemplateAssetUploadContentCheck($binary) );
      $input = $this->dispatcher->dispatch(new TemplateAssetUploadContentEnrich($binary, $binary) );
      return $this->writer->temporalStoreContent($input->getResult() );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}